//! Per-root-session terminal identity and shell preference.
//!
//! A terminal id is generated by Nano and written before `create`, so a lost
//! create response can be reconciled with `list`/`create` under the same id
//! instead of allocating a second shell. The file is private (0600) and lives
//! under the Nano data root, never in the official session log.

use std::fs::{self, OpenOptions};
use std::io::Write;
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

use serde::{Deserialize, Serialize};

const STORE_VERSION: u32 = 1;

/// One terminal id whose create response was not observed yet.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PendingTerminal {
    /// Pre-generated identity.
    pub id: String,
    /// Creation time, used only for diagnostics.
    pub created_at_ms: u64,
}

/// Persisted terminal preference and pending identities.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct StoreFile {
    /// Schema version.
    pub version: u32,
    /// Last explicitly selected shell path.
    #[serde(default)]
    pub shell_path: Option<String>,
    /// Identities whose create result is still unknown.
    #[serde(default)]
    pub pending: Vec<PendingTerminal>,
}

impl Default for StoreFile {
    fn default() -> Self {
        Self {
            version: STORE_VERSION,
            shell_path: None,
            pending: Vec::new(),
        }
    }
}

/// Private terminal state for one root session.
#[derive(Debug, Clone)]
pub struct TerminalStore {
    path: PathBuf,
    state: StoreFile,
}

impl TerminalStore {
    /// Open (or create) the store. A malformed file is an explicit error: the
    /// caller must not silently lose a pending identity.
    pub fn open(data_root: &Path, root_session_id: &str) -> Result<Self, String> {
        if root_session_id.is_empty()
            || root_session_id.len() > 128
            || !root_session_id.chars().all(|character| {
                character.is_ascii_alphanumeric() || character == '_' || character == '-'
            })
        {
            return Err(format!(
                "root session id {root_session_id:?} is not a safe identity; expected [A-Za-z0-9_-]{{1,128}}"
            ));
        }
        let directory = data_root.join("runtime-data").join(root_session_id);
        fs::create_dir_all(&directory).map_err(|error| {
            format!(
                "could not create terminal state directory {}: {error}",
                directory.display()
            )
        })?;
        set_private_directory(&directory)?;
        let path = directory.join("terminal.json");
        if !path.exists() {
            return Ok(Self {
                path,
                state: StoreFile::default(),
            });
        }
        let bytes = fs::read(&path).map_err(|error| {
            format!("could not read terminal state {}: {error}", path.display())
        })?;
        let state: StoreFile = serde_json::from_slice(&bytes).map_err(|error| {
            format!(
                "terminal state {} is not valid JSON: {error}",
                path.display()
            )
        })?;
        if state.version != STORE_VERSION {
            return Err(format!(
                "terminal state {} has unsupported version {}",
                path.display(),
                state.version
            ));
        }
        Ok(Self { path, state })
    }

    /// Last explicitly selected shell path.
    pub fn shell_path(&self) -> Option<&str> {
        self.state.shell_path.as_deref()
    }

    /// Remember an explicitly selected shell.
    pub fn set_shell_path(&mut self, path: Option<String>) -> Result<(), String> {
        self.state.shell_path = path;
        self.save()
    }

    /// Pre-generated ids whose create result is unknown.
    pub fn pending(&self) -> &[PendingTerminal] {
        &self.state.pending
    }

    /// Persist one pre-generated id before `create` is sent.
    pub fn set_pending(&mut self, id: &str) -> Result<(), String> {
        self.state.pending.retain(|pending| pending.id != id);
        self.state.pending.push(PendingTerminal {
            id: id.to_string(),
            created_at_ms: now_ms(),
        });
        self.save()
    }

    /// Forget one pending id after a definite result or reconciliation.
    pub fn clear_pending(&mut self, id: &str) -> Result<(), String> {
        let before = self.state.pending.len();
        self.state.pending.retain(|pending| pending.id != id);
        if self.state.pending.len() != before {
            self.save()?;
        }
        Ok(())
    }

    /// The state file path, for diagnostics.
    pub fn path(&self) -> &Path {
        &self.path
    }

    fn save(&self) -> Result<(), String> {
        let parent = self
            .path
            .parent()
            .ok_or_else(|| format!("terminal state {} has no parent", self.path.display()))?;
        let temporary = parent.join(format!(".terminal-{}.tmp", std::process::id()));
        let bytes = serde_json::to_vec_pretty(&self.state)
            .map_err(|error| format!("could not encode terminal state: {error}"))?;
        let mut file = OpenOptions::new()
            .create(true)
            .truncate(true)
            .write(true)
            .open(&temporary)
            .map_err(|error| {
                format!(
                    "could not write terminal state {}: {error}",
                    temporary.display()
                )
            })?;
        set_private_file(&temporary)?;
        file.write_all(&bytes)
            .and_then(|()| file.sync_all())
            .map_err(|error| {
                format!(
                    "could not write terminal state {}: {error}",
                    temporary.display()
                )
            })?;
        drop(file);
        fs::rename(&temporary, &self.path).map_err(|error| {
            format!(
                "could not replace terminal state {}: {error}",
                self.path.display()
            )
        })?;
        Ok(())
    }
}

fn now_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_millis().min(u128::from(u64::MAX)) as u64)
        .unwrap_or(0)
}

#[cfg(unix)]
fn set_private_directory(path: &Path) -> Result<(), String> {
    use std::os::unix::fs::PermissionsExt;
    fs::set_permissions(path, fs::Permissions::from_mode(0o700))
        .map_err(|error| format!("could not set permissions on {}: {error}", path.display()))
}

#[cfg(not(unix))]
fn set_private_directory(_path: &Path) -> Result<(), String> {
    Ok(())
}

#[cfg(unix)]
fn set_private_file(path: &Path) -> Result<(), String> {
    use std::os::unix::fs::PermissionsExt;
    fs::set_permissions(path, fs::Permissions::from_mode(0o600))
        .map_err(|error| format!("could not set permissions on {}: {error}", path.display()))
}

#[cfg(not(unix))]
fn set_private_file(_path: &Path) -> Result<(), String> {
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn temp_root(name: &str) -> PathBuf {
        let path =
            std::env::temp_dir().join(format!("nano-terminal-store-{name}-{}", std::process::id()));
        let _ = fs::remove_dir_all(&path);
        fs::create_dir_all(&path).unwrap();
        path
    }

    #[test]
    fn persists_pending_ids_and_shell_choice() {
        let root = temp_root("roundtrip");
        let mut store = TerminalStore::open(&root, "session-a").unwrap();
        store.set_pending("term-1").unwrap();
        store.set_shell_path(Some("/bin/zsh".to_string())).unwrap();

        let reopened = TerminalStore::open(&root, "session-a").unwrap();
        assert_eq!(reopened.pending()[0].id, "term-1");
        assert_eq!(reopened.shell_path(), Some("/bin/zsh"));

        let mut reopened = reopened;
        reopened.clear_pending("term-1").unwrap();
        assert!(TerminalStore::open(&root, "session-a")
            .unwrap()
            .pending()
            .is_empty());
    }

    #[test]
    fn malformed_state_is_explicit() {
        let root = temp_root("malformed");
        let directory = root.join("runtime-data").join("session-a");
        fs::create_dir_all(&directory).unwrap();
        fs::write(directory.join("terminal.json"), b"not json").unwrap();
        let error = TerminalStore::open(&root, "session-a").unwrap_err();
        assert!(error.contains("not valid JSON"), "{error}");
    }
}

#[cfg(test)]
mod identity_tests {
    use super::*;

    #[test]
    fn unsafe_session_ids_are_rejected_before_any_path_join() {
        let root = std::env::temp_dir().join(format!("nano-terminal-id-{}", std::process::id()));
        for id in ["", "../escape", "/absolute", "with/slash", "with space"] {
            let error = TerminalStore::open(&root, id).unwrap_err();
            assert!(error.contains("not a safe identity"), "{id:?}: {error}");
        }
        assert!(TerminalStore::open(&root, "session-abc_123").is_ok());
    }
}
